import 'dart:io';

import 'package:flutter_test/flutter_test.dart';
import 'package:intono_app/src/scales/scale.dart';

// The scale data (ADR 0011) is generated by tools/scales/gen_scales.py; these tests check it independently of the generator: pitch from
// string + finger, intervals per scale type, spelling, range, shape. Written before the Dart model.

const openMidi = {'G': 55, 'D': 62, 'A': 69, 'E': 76};
const stepsUp = {
  'major': [2, 2, 1, 2, 2, 2, 1],
  'natural_minor': [2, 1, 2, 2, 1, 2, 2],
  'harmonic_minor': [2, 1, 2, 2, 1, 3, 1],
  'melodic_minor': [2, 1, 2, 2, 2, 2, 1],
};
const stepsDown = {'melodic_minor': [2, 1, 2, 2, 1, 2, 2]};
const letterPc = {'C': 0, 'D': 2, 'E': 4, 'F': 5, 'G': 7, 'A': 9, 'B': 11};

int midiOfName(String n) {
  final m = RegExp(r'^([A-G])(bb|b|##|#)?(-?\d)$').firstMatch(n)!;
  final acc = {null: 0, 'b': -1, 'bb': -2, '#': 1, '##': 2}[m.group(2)]!;
  return (int.parse(m.group(3)!) + 1) * 12 + letterPc[m.group(1)]! + acc;
}

void main() {
  final lib = ScaleLibrary.fromJsonString(File('assets/scales/beginner.json').readAsStringSync());

  test('the beginner keys are all there, every minor in its three forms', () {
    final keys = lib.scales.map((s) => '${s.key}/${s.type}').toSet();
    for (final k in ['G major', 'D major', 'A major', 'C major', 'F major']) {
      expect(keys, contains('$k/major'));
    }
    for (final k in ['A minor', 'D minor', 'E minor']) {
      for (final t in ['natural_minor', 'harmonic_minor', 'melodic_minor']) {
        expect(keys, contains('$k/$t'));
      }
    }
    expect(lib.byId('g_major_2oct'), isNotNull);
    expect(lib.byId('a_melodic_minor_2oct'), isNotNull);
    expect(lib.byId('d_major_2oct'), isNull, reason: 'D major over two octaves leaves first position');
  });

  test('every note is where its string and finger put it, in first position', () {
    const offsets = {0: [0], 1: [1, 2], 2: [3, 4], 3: [5, 6], 4: [7]};
    for (final s in lib.scales) {
      for (final n in s.notes) {
        final off = n.midi - openMidi[n.string]!;
        expect(offsets[n.finger], contains(off), reason: '${s.id} ${n.name}: ${n.string} string finger ${n.finger}');
        expect(n.midi, inInclusiveRange(55, 83), reason: '${s.id} ${n.name}');
        if (n.finger == 4) expect(n.string, 'E', reason: 'a 4th finger only where no higher open string exists');
      }
    }
  });

  test('spelling matches pitch, and letters run by step', () {
    for (final s in lib.scales) {
      final up = s.notes.sublist(0, s.ascendingCount);
      for (final n in s.notes) {
        expect(midiOfName(n.name), n.midi, reason: '${s.id} ${n.name}');
      }
      for (var i = 1; i < up.length; i++) {
        final a = 'CDEFGAB'.indexOf(up[i - 1].name[0]);
        final b = 'CDEFGAB'.indexOf(up[i].name[0]);
        expect(b, (a + 1) % 7, reason: '${s.id}: one letter per scale step');
      }
    }
  });

  test('intervals follow the scale type up and down; the top tonic is played once; the shape is symmetric', () {
    for (final s in lib.scales) {
      final up = s.notes.sublist(0, s.ascendingCount);
      final down = s.notes.sublist(s.ascendingCount - 1); // from the top tonic down
      expect(up.length, 7 * s.octaves + 1, reason: s.id);
      expect(s.notes.length, 2 * up.length - 1, reason: s.id);
      expect(up.first.midi, down.last.midi);
      expect(up.last.midi - up.first.midi, 12 * s.octaves);
      final su = stepsUp[s.type]!;
      final sd = stepsDown[s.type] ?? su;
      for (var i = 1; i < up.length; i++) {
        expect(up[i].midi - up[i - 1].midi, su[(i - 1) % 7], reason: '${s.id} up step $i');
      }
      for (var i = 1; i < down.length; i++) {
        // descending: the reverse of the down step pattern
        expect(down[i - 1].midi - down[i].midi, sd[(sd.length * s.octaves - i) % 7], reason: '${s.id} down step $i');
      }
    }
  });

  test('the lowest tonic at or above the open G string', () {
    for (final s in lib.scales) {
      expect(s.notes.first.midi, inInclusiveRange(55, 66), reason: s.id);
    }
  });
}
